def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    color = next(v for row in grid for v in row if v not in (1,))
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == color]
        for c in range(min(cols, default=0), max(cols, default=-1) + 1):
            if grid[r][c] == 1:
                out[r][c] = 2
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == color]
        for r in range(min(rows, default=0), max(rows, default=-1) + 1):
            if grid[r][c] == 1:
                out[r][c] = 2
    return out
